package com.hbm.satellite;
import java.util.Map;import java.util.HashMap;import net.minecraft.resources.ResourceKey;import net.minecraft.world.level.Level;
/** Numeric source dimension IDs map explicitly to real modern dimension keys, never to registry iteration order. */
public final class SatelliteDimensions {private static final Map<Integer,ResourceKey<Level>> DIMENSIONS=new HashMap<>();static{bind(0,Level.OVERWORLD);bind(-1,Level.NETHER);bind(1,Level.END);}public static void bind(int sourceId,ResourceKey<Level> key){DIMENSIONS.put(sourceId,key);}public static ResourceKey<Level> resolve(int sourceId){return DIMENSIONS.get(sourceId);}/** Reverse only explicitly bound original IDs; no registry-order or hash-derived fake dimension numbers. */public static Integer sourceId(ResourceKey<Level> key){return DIMENSIONS.entrySet().stream().filter(entry->entry.getValue().equals(key)).map(Map.Entry::getKey).min(Integer::compareTo).orElse(null);}private SatelliteDimensions(){}}
